def rank_modification_reviews(reviews: list[Review]) -> list[Review]:
    """
    Sort modification reviews by community helpful votes and quality signals.

    Args:
        reviews: All reviews for a recipe

    Returns:
        Modification reviews sorted best-first (helpful_count, rating, featured)
    """
    modification_reviews = [review for review in reviews if review.has_modification]

    def sort_key(review: Review) -> tuple[int, int, int]:
        return (
            -(review.helpful_count or 0),
            -(review.rating or 0),
            0 if review.is_featured else 1,
        )

    return sorted(modification_reviews, key=sort_key)

