def extract_helpful_count(review_elem) -> int:
    """
    Extract the number of helpful/thumbs-up votes on a review element.

    Args:
        review_elem: BeautifulSoup element for a single review

    Returns:
        Helpful vote count, or 0 if not found
    """
    helpful_button = review_elem.select_one(".mm-recipes-ugc-shared-helpful-button")
    if helpful_button:
        match = re.search(r"(\d+)", helpful_button.get_text(strip=True))
        if match:
            return int(match.group(1))

    elements_to_check = [review_elem, *review_elem.find_all(True)]
    for elem in elements_to_check:
        count_attr = elem.get("data-helpful-count")
        if count_attr is not None:
            try:
                return int(str(count_attr).replace(",", ""))
            except ValueError:
                pass

    helpful_button = review_elem.find(
        "button", attrs={"class": re.compile(r"helpful-button", re.I)}
    )
    if helpful_button:
        match = re.search(r"(\d+)", helpful_button.get_text(strip=True))
        if match:
            return int(match.group(1))

    full_text = review_elem.get_text()
    helpful_patterns = [
        r"(\d+)\s+found this helpful",
        r"Helpful\s*\((\d+)\)",
        r"(\d+)\s+people found this helpful",
    ]
    for pattern in helpful_patterns:
        match = re.search(pattern, full_text, re.IGNORECASE)
        if match:
            return int(match.group(1))

    return 0


